// pMMFake implements control.Control; each call is recorded with its arguments.
type pMMFake struct {
	mu     sync.Mutex
	calls  []string
	status control.Status
}

func (f *pMMFake) rec(m string, args ...any) {
	f.mu.Lock()
	defer f.mu.Unlock()
	s := m + "("
	for i, a := range args {
		if i > 0 {
			s += ", "
		}
		s += fmt.Sprintf("%#v", a)
	}
	f.calls = append(f.calls, s+")")
}

